</head>
<body>
  <h1>Falling Sand</h1>

  <div id="canvas-container">
    <canvas id="sand"></canvas>
  </div>

  <div class="controls">
    <button id="mat-sand" class="active">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Eraser</button>
    <button id="clear">Clear All</button>
  </div>

  <div class="stats">
    <span id="stats-info">Grid: 80×80 | FPS: 60</span>
  </div>

  <script>
    // Grid configuration
    const GRID_W = 80;
    const GRID_H = 80;
    const CELL_SIZE = 5; // 400px / 80 = 5px per cell

    // Material constants
    const EMPTY = 'empty';
    const SAND = 'sand';
    const WATER = 'water';
    const WALL = 'wall';
    const ACID = 'acid';

    // Color palette
    const COLORS = {
      empty: '#1e1e1e',
      sand: '#c2a66d',
      water: '#3b9be0',
      wall: '#555555',
      acid: '#7cb342'
    };

    // Simulation state
    let grid = [];
    let nextGrid = [];
    let selectedMaterial = SAND;
    let isDrawing = false;

    // Initialize grid
    function initGrid() {
      grid = [];
      for (let y = 0; y < GRID_H; y++) {
        grid[y] = [];
        for (let x = 0; x < GRID_W; x++) {
          grid[y][x] = EMPTY;
        }
      }
      nextGrid = JSON.parse(JSON.stringify(grid));
    }

    // Get cell value
    function getCell(x, y) {
      if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return WALL;
      return grid[y][x];
    }

    // Set cell value
    function setCell(x, y, material) {
      if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return;
      nextGrid[y][x] = material;
    }

    // Swap cells
    function swapCells(x1, y1, x2, y2) {
      if (x2 < 0 || x2 >= GRID_W || y2 < 0 || y2 >= GRID_H) return false;
      const temp = nextGrid[y1][x1];
      nextGrid[y1][x1] = nextGrid[y2][x2];
      nextGrid[y2][x2] = temp;
      return true;
    }

    // Check if cell is empty or can be displaced
    function canMoveTo(x, y, material) {
      if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return false;
      const cell = nextGrid[y][x];
      if (cell === EMPTY) return true;
      if (material === SAND && (cell === WATER || cell === ACID)) return true;
      if (material === WATER && cell === EMPTY) return true;
      if (material === ACID && (cell === EMPTY || cell === SAND || cell === WATER || cell === WALL)) return true;
      return false;
    }

    // Simulate one step
    function tick() {
      // Copy grid to nextGrid
      for (let y = 0; y < GRID_H; y++) {
        for (let x = 0; x < GRID_W; x++) {
          nextGrid[y][x] = grid[y][x];
        }
      }

      // Process from bottom to top to avoid particles moving multiple cells per step
      for (let y = GRID_H - 2; y >= 0; y--) {
        for (let x = 0; x < GRID_W; x++) {
          const cell = grid[y][x];

          if (cell === SAND) {
            handleSand(x, y);
          } else if (cell === WATER) {
            handleWater(x, y);
          } else if (cell === ACID) {
            handleAcid(x, y);
          }
        }
      }

      // Swap grids
      const temp = grid;
      grid = nextGrid;
      nextGrid = temp;
    }

    function handleSand(x, y) {
      const below = getCell(x, y + 1);

      // Fall straight down
      if (below === EMPTY) {
        swapCells(x, y, x, y + 1);
        return;
      }

      // Swap with water or acid (sand sinks)
      if (below === WATER || below === ACID) {
        swapCells(x, y, x, y + 1);
        return;
      }

      // Try to slide diagonally
      const dirs = Math.random() < 0.5 ? 
        [[x - 1, y + 1], [x + 1, y + 1]] : 
        [[x + 1, y + 1], [x - 1, y + 1]];

      for (const [nx, ny] of dirs) {
        if (canMoveTo(nx, ny, SAND)) {
          swapCells(x, y, nx, ny);
          return;
        }
      }
    }

    function handleWater(x, y) {
      const below = getCell(x, y + 1);

      // Fall straight down
      if (below === EMPTY) {
        swapCells(x, y, x, y + 1);
        return;
      }

      // Try diagonal fallback
      const diagDirs = Math.random() < 0.5 ? 
        [[x - 1, y + 1], [x + 1, y + 1]] : 
        [[x + 1, y + 1], [x - 1, y + 1]];

      for (const [nx, ny] of diagDirs) {
        if (canMoveTo(nx, ny, WATER)) {
          swapCells(x, y, nx, ny);
          return;
        }
      }

      // Spread horizontally
      const horiDirs = Math.random() < 0.5 ? 
        [[x - 1, y], [x + 1, y]] : 
        [[x + 1, y], [x - 1, y]];

      for (const [nx, ny] of horiDirs) {
        if (nx >= 0 && nx < GRID_W && getCell(nx, ny) === EMPTY) {
          swapCells(x, y, nx, ny);
          return;
        }
      }
    }

    function handleAcid(x, y) {
      // Dissolve adjacent cells
      const adjacent = [
        [x, y + 1],
        [x - 1, y],
        [x + 1, y],
        [x, y - 1]
      ];

      for (const [nx, ny] of adjacent) {
        if (nx >= 0 && nx < GRID_W && ny >= 0 && ny < GRID_H) {
          const cell = nextGrid[ny][nx];
          if (cell === SAND || cell === WALL) {
            nextGrid[ny][nx] = EMPTY;
          }
        }
      }

      // Move like water
      const below = getCell(x, y + 1);

      if (below === EMPTY) {
        swapCells(x, y, x, y + 1);
        return;
      }

      // Try diagonal
      const diagDirs = Math.random() < 0.5 ? 
        [[x - 1, y + 1], [x + 1, y + 1]] : 
        [[x + 1, y + 1], [x - 1, y + 1]];

      for (const [nx, ny] of diagDirs) {
        if (canMoveTo(nx, ny, ACID)) {
          swapCells(x, y, nx, ny);
          return;
        }
      }

      // Spread horizontally
      const horiDirs = Math.random() < 0.5 ? 
        [[x - 1, y], [x + 1, y]] : 
        [[x + 1, y], [x - 1, y]];

      for (const [nx, ny] of horiDirs) {
        if (nx >= 0 && nx < GRID_W && getCell(nx, ny) === EMPTY) {
          swapCells(x, y, nx, ny);
          return;
        }
      }
    }

    // Rendering
    const canvas = document.getElementById('sand');
    const ctx = canvas.getContext('2d');
    canvas.width = GRID_W * CELL_SIZE;
    canvas.height = GRID_H * CELL_SIZE;

    function render() {
      ctx.fillStyle = COLORS.empty;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      for (let y = 0; y < GRID_H; y++) {
        for (let x = 0; x < GRID_W; x++) {
          const cell = grid[y][x];
          if (cell !== EMPTY) {
            ctx.fillStyle = COLORS[cell];
            ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
          }
        }
      }
    }

    // Input handling
    const matButtons = {
      'mat-sand': SAND,
      'mat-water': WATER,
      'mat-wall': WALL,
      'mat-acid': ACID,
      'mat-empty': EMPTY
    };

    Object.entries(matButtons).forEach(([btnId, material]) => {
      document.getElementById(btnId).addEventListener('click', () => {
        selectedMaterial = material;
        document.querySelectorAll('.controls button:not(#clear)').forEach(btn => {
          btn.classList.remove('active');
        });
        document.getElementById(btnId).classList.add('active');
      });
    });

    document.getElementById('clear').addEventListener('click', () => {
      initGrid();
      render();
    });

    // Canvas drawing
    function getCanvasPos(e) {
      const rect = canvas.getBoundingClientRect();
      const x = Math.floor((e.clientX - rect.left) / (rect.width / GRID_W));
      const y = Math.floor((e.clientY - rect.top) / (rect.height / GRID_H));
      return { x, y };
    }

    canvas.addEventListener('mousedown', (e) => {
      isDrawing = true;
      const { x, y } = getCanvasPos(e);
      if (x >= 0 && x < GRID_W && y >= 0 && y < GRID_H) {
        grid[y][x] = selectedMaterial;
        render();
      }
    });

    canvas.addEventListener('mousemove', (e) => {
      if (!isDrawing) return;
      const { x, y } = getCanvasPos(e);
      if (x >= 0 && x < GRID_W && y >= 0 && y < GRID_H) {
        grid[y][x] = selectedMaterial;
        render();
      }
    });

    canvas.addEventListener('mouseup', () => {
      isDrawing = false;
    });

    canvas.addEventListener('mouseleave', () => {
      isDrawing = false;
    });

    // Animation loop
    let frameCount = 0;
    let lastTime = performance.now();
    let fps = 60;

    function animate(time) {
      frameCount++;
      const elapsed = time - lastTime;
      if (elapsed >= 1000) {
        fps = frameCount;
        frameCount = 0;
        lastTime = time;
        document.getElementById('stats-info').textContent = `Grid: ${GRID_W}×${GRID_H} | FPS: ${fps}`;
      }

      tick();
      render();
      requestAnimationFrame(animate);
    }

    // Public API
    window.sim = {
      w: GRID_W,
      h: GRID_H,
      tick(n) {
        for (let i = 0; i < n; i++) {
          tick();
        }
      },
      get(x, y) {
        if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return EMPTY;
        return grid[y][x];
      },
      set(x, y, material) {
        if (x >= 0 && x < GRID_W && y >= 0 && y < GRID_H) {
          grid[y][x] = material;
        }
      },
      clear() {
        initGrid();
      }
    };

    // Initialize
    initGrid();
    render();
    requestAnimationFrame(animate);
  </script>
</body>
</html>
